\begin{example}[Cut Loci]
\label{ex:cut-loci}
\dcref{ch10:10.30}
\begin{enumerate}
\item[(a)] For the round sphere $(S^n(R),\bar g_R)$,
$\operatorname{Cut}(p)=\{-p\}$.
\item[(b)] For $S^n(R)\times\mathbb R^m$ with the product metric,
\[
\operatorname{Cut}(p,x)=\{-p\}\times\mathbb R^m.
\]
\end{enumerate}
\end{example}

